const CAREER_TRACKS={
  '内容 / 品牌 / 市场':['内容','品牌','市场','新媒体','运营','增长','投放','campaign','marketing','seo','社媒','短视频','直播'],
  '产品 / 项目 / 运营':['产品','项目管理','项目运营','用户运营','活动运营','策略运营','program','product','roadmap','需求分析'],
  '销售 / 商务 / 客户成功':['销售','商务','客户成功','渠道','大客户','续约','回款','quota','pipeline','crm','成交'],
  '技术 / 数据 / AI':['开发','工程师','技术','数据','算法','测试','运维','前端','后端','python','java','sql','ai','模型','云'],
  '设计 / 创意':['设计','视觉','交互','用户体验','ui','ux','平面','创意','作品集'],
  '教育 / 研究':['教师','教育','课程','教研','培训','研究','论文','学术','实验'],
  '职能 / 综合管理':['人力','招聘','财务','法务','行政','采购','供应链','管理','hr','finance']
};
const TERM_GROUPS={
  '内容策划':['内容策划','选题策划','脚本','文案','内容运营'], '数据分析':['数据分析','数据复盘','sql','excel','tableau','python'],
  '项目推进':['项目推进','项目管理','跨部门','交付','进度管理'], '用户洞察':['用户洞察','用户研究','用户需求','市场洞察'],
  '增长转化':['增长','转化','roi','roas','cac','获客','留存'], '团队协作':['团队协作','跨团队','沟通协调','stakeholder'],
  '客户经营':['客户成功','客户关系','续约','crm','大客户'], '销售结果':['销售额','成交','回款','pipeline','quota'],
  '产品能力':['产品设计','需求分析','roadmap','原型','产品规划'], '技术能力':['开发','编程','系统设计','api','数据库','云计算'],
  '设计能力':['视觉设计','交互设计','ui','ux','设计系统'], '教学研究':['课程设计','教学','教研','研究','论文'],
  '领导管理':['团队管理','带教','招聘','绩效','预算','战略']
};
function normCareerText(v){return String(v||'').toLowerCase().replace(/\s+/g,' ')}
function splitJdLines(text){return String(text||'').split(/\n|[。；]/).map(x=>x.trim()).filter(x=>x.length>5)}
function detectCareerTrack(text){const s=normCareerText(text),scores=Object.entries(CAREER_TRACKS).map(([name,terms])=>[name,terms.reduce((n,t)=>n+(s.includes(t)?1:0),0)]).sort((a,b)=>b[1]-a[1]);return scores[0][1]?scores[0][0]:'通用 / 其他职业'}
function findRequirements(text){const lines=splitJdLines(text),must=[],nice=[];for(const line of lines){if(/加分|优先|更佳|bonus|preferred|plus/i.test(line))nice.push(line);else if(/要求|负责|需要|具备|熟悉|能够|经验|能力|资格|qualification|requirement|responsib/i.test(line))must.push(line)}return{must:must.slice(0,8),nice:nice.slice(0,5)}}
function termKeywords(text){const s=normCareerText(text),found=[];for(const [label,aliases] of Object.entries(TERM_GROUPS)){const hits=aliases.filter(x=>s.includes(x.toLowerCase()));if(hits.length)found.push({label,exact:hits[0],aliases})}for(const k of words())if(!found.some(x=>x.exact===k)&&found.length<12)found.push({label:k,exact:k,aliases:[k]});return found.slice(0,12)}
function evidenceFor(term){const experiences=state.profile.experiences||[],all=[state.profile.selfEvaluation,state.profile.education,state.profile.skills,state.portfolio?.text,...experiences.map(x=>Object.values(x).join(' '))].filter(Boolean);const exact=all.find(x=>term.aliases.some(a=>normCareerText(x).includes(a.toLowerCase())));if(exact){const exp=experiences.find(x=>term.aliases.some(a=>normCareerText(Object.values(x).join(' ')).includes(a.toLowerCase())));return{level:'strong',label:'有证据',source:exp?`${exp.title}${exp.role?' · '+exp.role:''}`:'原始资料 / 作品集'}}const group=Object.values(TERM_GROUPS).find(a=>a.includes(term.exact));const adjacent=group&&all.find(x=>group.some(a=>normCareerText(x).includes(a.toLowerCase())));return adjacent?{level:'adjacent',label:'相近证据',source:'需要 AI 谨慎转述，不可写成直接经验'}:{level:'missing',label:'无证据',source:'从简历中排除，不能为了匹配而补写'}}
function analyzeCareerJob(){const req=findRequirements(state.job.jdText),keywords=termKeywords(state.job.jdText),evidence=keywords.map(x=>({...x,evidence:evidenceFor(x)})),analysis={track:detectCareerTrack(state.job.jobTitle+'\n'+state.job.jdText),must:req.must,nice:req.nice,keywords,evidence,generatedAt:new Date().toISOString()};state.job.analysis=analysis;save();return analysis}
function renderCareerAnalysis(){const analysis=analyzeCareerJob(),box=document.querySelector('#careerAnalysis');box.hidden=false;document.querySelector('#careerTrack').textContent=`${analysis.track} · ${state.job.jobTitle||'待确认岗位名称'}`;const priorities=[...analysis.must.slice(0,5).map(x=>['must','必须项',x]),...analysis.nice.slice(0,3).map(x=>['nice','加分项',x])];document.querySelector('#rolePriorities').innerHTML=priorities.length?priorities.map(x=>`<div class="priority-row ${x[0]}"><i>${x[1]}</i><span>${esc(x[2])}</span></div>`).join(''):'<div class="empty-note">JD 分段不明显，AI 将结合岗位名称和完整正文分析。</div>';document.querySelector('#evidenceScorecard').innerHTML=analysis.evidence.slice(0,8).map(x=>`<div class="evidence-row ${x.evidence.level}"><i>${x.evidence.label}</i><span>${esc(x.label)}<em>${esc(x.evidence.source)}</em></span></div>`).join('');document.querySelector('#atsKeywords').textContent=analysis.keywords.map(x=>x.exact).join(' · ')||'尚未识别';const gaps=analysis.evidence.filter(x=>x.evidence.level==='missing').map(x=>x.label);document.querySelector('#honestGaps').textContent=gaps.join(' · ')||'暂未发现明显缺口';renderFit()}
function resumeQualityReport(root){const text=root.innerText||'',jd=state.job.analysis||analyzeCareerJob(),items=[];const missing=jd.keywords.filter(x=>x.evidence.level==='strong'&&!normCareerText(text).includes(x.exact.toLowerCase())).map(x=>x.exact);items.push({ok:!missing.length,title:'ATS 关键词',detail:missing.length?'有证据但尚未写入：'+missing.join('、'):'有证据的重点词已自然覆盖'});const unsupported=jd.evidence.filter(x=>x.evidence.level==='missing'&&normCareerText(text).includes(x.exact.toLowerCase())).map(x=>x.exact);items.push({ok:!unsupported.length,title:'事实边界',detail:unsupported.length?'疑似写入无证据要求：'+unsupported.join('、'):'未发现为迎合 JD 硬加的能力'});const aiWords=['赋能','深耕','抓手','闭环','卓越','充满热情','结果导向','具备较强的','拥有丰富的','成功地','有效地'],hits=aiWords.filter(x=>text.includes(x));items.push({ok:!hits.length,title:'去 AI 味',detail:hits.length?'建议删除套话：'+hits.join('、'):'未发现常见 AI 套话'});const experienceCount=root.querySelectorAll('.resume-item').length,sourceCount=(state.profile.experiences||[]).length;items.push({ok:experienceCount>=sourceCount,title:'经历完整性',detail:`修改稿 ${experienceCount} 份 / 原始事实 ${sourceCount} 份`});const report=document.querySelector('#qualityReport');report.hidden=false;report.innerHTML=`<h3>生成质量检查</h3><div class="quality-grid">${items.map(x=>`<div class="quality-item ${x.ok?'pass':'warn'}"><b>${x.ok?'通过':'需确认'} · ${x.title}</b><div>${esc(x.detail)}</div></div>`).join('')}</div>`;return items}
const originalAnalyzeButton=document.querySelector('#analyzeJd');originalAnalyzeButton.onclick=()=>{if(state.job.jdText.trim().length<30)return toast('请先粘贴完整 JD');renderCareerAnalysis();go('generate')};
if(state.job.jdText.trim().length>=30)renderCareerAnalysis();
window.analyzeCareerJob=analyzeCareerJob;window.renderCareerAnalysis=renderCareerAnalysis;window.resumeQualityReport=resumeQualityReport;
